olor--theme-5)","text":"var(--wp--preset--color--theme-1)"},"blocks":{"core/separator":{"color":{"text":"var(--wp--preset--color--theme-1)"}},"core/social-links":{"color":{"text":"currentColor"}}},"elements":{"button":{"color":{"background":"var(--wp--preset--color--theme-4)","text":"var(--wp--preset--color--theme-1)"},":hover":{"color":{"background":"color-mix(in srgb, var(--wp--preset--color--theme-4) 90%, #000)","text":"var(--wp--preset--color--theme-1)"}}}}}}}},"elements":{"button":{"color":{"background":"var(--wp--preset--color--theme-4)","text":"var(--wp--preset--color--theme-1)"},":hover":{"color":{"background":"color-mix(in srgb, var(--wp--preset--color--theme-4) 90%, #000)","text":"var(--wp--preset--color--theme-1)"}}}},"css":".wpcom-ai-text-wrap-fix {
	min-width: 0;
	width: 100%;
	max-width: none;
	height: auto;
	max-height: none;
	min-height: 0;
	box-sizing: border-box;
	overflow: visible;
}

.wpcom-ai-text-wrap-fix * {
	min-width: 0;
	max-width: 100%;
	white-space: normal;
	overflow-wrap: anywhere;
	word-break: normal;
}

@media (max-width: 782px) {
	.wpcom-ai-text-wrap-fix {
		width: 100%;
	}
}

.wpcom-ai-herts-outdoor-backdrop {
	background-image: url('https://tabish906.wordpress.com/wp-content/uploads/2026/11/active-life-herts-6ae8fec494853.png');
	background-size: cover;
	background-position: center;
	overflow: hidden;
	box-sizing: border-box;
}

.wpcom-ai-herts-outdoor-backdrop * {
	box-sizing: border-box;
	max-width: 100%;
}

.wp-block-group,
.wp-block-column,
.wp-block-columns {
	box-sizing: border-box;
	max-width: 100%;
	overflow-wrap: anywhere;
}

body {
	overflow-x: hidden;
}

/* Keep the related-content cards equal in each grid row and align actions. */
.wpcom-ai-card-grid {
	align-items: stretch;
}

.wpcom-ai-card-grid > .wpcom-ai-grid-card {
	display: flex;
	flex-direction: column;
	height: 100%;
	box-sizing: border-box;
}

.wpcom-ai-card-grid > .wpcom-ai-grid-card > .wp-block-buttons {
	margin-top: auto;
}

.wpcom-ai-card-grid > .wpcom-ai-grid-card {
	border: 1px solid rgba(0, 0, 0, 0.06);
	box-shadow: 0 4px 16px rgba(0, 0, 0, 0.06);
	transition: box-shadow 0.25s ease, transform 0.25s ease;
}

.wpcom-ai-card-grid > .wpcom-ai-grid-card:hover {
	box-shadow: 0 10px 28px rgba(0, 0, 0, 0.12);
	transform: translateY(-2px);
}

.wpcom-ai-card-grid .wp-block-heading {
	letter-spacing: 0.01em;
	margin-bottom: var(--wp--preset--spacing--30);
}

@media (max-width: 600px) {
	.wpcom-ai-card-grid {
		padding-left: var(--wp--preset--spacing--40) !important;
		padding-right: var(--wp--preset--spacing--40) !important;
		grid-template-columns: 1fr !important;
	}
}

@media (max-width: 600px) {
	.wpcom-ai-herts-outdoor-backdrop {
		padding-left: var(--wp--preset--spacing--40) !important;
		padding-right: var(--wp--preset--spacing--40) !important;
	}

	.wpcom-ai-herts-outdoor-backdrop h1 {
		font-size: clamp(28px, 8vw, 42px) !important;
		line-height: 1.15;
	}
}

/* Location cards: uniform two-column grid with equal width/height cards */
.wpcom-ai-location-grid.wpcom-ai-location-grid {
	display: grid;
	grid-template-columns: repeat(2, 1fr);
	align-items: stretch;
	justify-items: stretch;
}

.wpcom-ai-location-grid.wpcom-ai-location-grid > * {
	width: 100%;
	box-sizing: border-box;
}

@media (max-width: 782px) {
	.wpcom-ai-location-grid.wpcom-ai-location-grid {
		grid-template-columns: 1fr;
	}
}

/* Guide cards: uniform two-column grid with equal width/height cards */
.wpcom-ai-guide-grid.wpcom-ai-guide-grid {
	display: grid;
	grid-template-columns: repeat(2, 1fr);
	align-items: stretch;
	justify-items: stretch;
}

.wpcom-ai-guide-grid.wpcom-ai-guide-grid > .wpcom-ai-grid-card {
	width: 100%;
	box-sizing: border-box;
}

@media (max-width: 782px) {
	.wpcom-ai-guide-grid.wpcom-ai-guide-grid {
		grid-template-columns: 1fr;
	}
}

/* Keep content within the activity columns aligned consistently. */
.wpcom-ai-column-align > .wp-block-column {
	display: flex;
	flex-direction: column;
}

.wpcom-ai-column-align > .wp-block-column > .wp-block-cover {
	display: flex;
	flex-direction: column;
	height: 100%;
}

.wpcom-ai-column-align > .wp-block-column > .wp-block-cover > .wp-block-cover__inner-container {
	display: flex;
	flex-direction: column;
	height: 100%;
}

.wpcom-ai-column-align > .wp-block-column > .wp-block-cover > .wp-block-cover__inner-container > p:last-child {
	margin-top: auto;
}

/* Readable heading overlay near the bottom of the garden image */
.wpcom-ai-guide-heading {
	text-shadow: 0 2px 10px rgba(0, 0, 0, 0.55);
}"},"settings":{"color":{"palette":{"theme":[{"color":"#FCEFE6","name":"Color 1","slug":"theme-1"},{"color":"#000000","name":"Color 5","slug":"theme-5"},{"color":"#fff9f5","name":"Color 3","slug":"theme-3"},{"color":"#DF3331","name":"Color 4","slug":"theme-4"}]},"gradients":{"theme":[{"slug":"gradient-text-transparent","gradient":"linear-gradient(to bottom, var(--wp--preset--color--theme-5) -50%, transparent 50%)","name":"Text to Transparent"},{"slug":"gradient-1-2","gradient":"linear-gradient(to bottom, var(--wp--preset--color--theme-1) 0%, var(--wp--preset--color--theme-5) 100%)","name":"Gradient 1"},{"slug":"gradient-1-3","gradient":"linear-gradient(to bottom, var(--wp--preset--color--theme-1) 0%, var(--wp--preset--color--theme-3) 100%)","name":"Gradient 2"},{"slug":"gradient-1-4","gradient":"linear-gradient(to bottom, var(--wp--preset--color--theme-1) 0%, var(--wp--preset--color--theme-4) 100%)","name":"Gradient 3"},{"slug":"gradient-2-3","gradient":"linear-gradient(to bottom, var(--wp--preset--color--theme-5) 0%, var(--wp--preset--color--theme-3) 100%)","name":"Gradient 4"},{"slug":"gradient-2-4","gradient":"linear-gradient(to bottom, var(--wp--preset--color--theme-5) 0%, var(--wp--preset--color--theme-4) 100%)","name":"Gradient 5"},{"slug":"gradient-3-4","gradient":"linear-gradient(to bottom, var(--wp--preset--color--theme-3) 0%, var(--wp--preset--color--theme-4) 100%)","name":"Gradient 6"}]},"duotone":{"theme":[{"colors":["#DF3331","#fff9f5"],"slug":"duotone-1","name":"Duotone 1"}]}}},"isGlobalStylesUserThemeJSON":true,"version":3}

{"styles":{"color":{"gradient":"linear-gradient(135deg,rgb(190,228,230) 0%,rgb(242,239,208) 53%,rgb(168,209,173) 100%)","text":"var(--wp--preset--color--custom-purple)"},"typography":{"fontFamily":"var(--wp--preset--font-family--open-sans)","fontStyle":"normal","fontWeight":"400","fontSize":"var(--wp--preset--font-size--large)"},"blocks":{"core/heading":{"typography":{"fontStyle":"normal","fontWeight":"400"}}},"css":".wpcom-ai-feature-card.wpcom-ai-feature-card {
	border: 1px solid rgba(11,48,59,0.12);
	box-shadow: 0 6px 20px rgba(11,48,59,0.08);
	display: flex;
	flex-direction: column;
	justify-content: space-between;
	height: 100%;
}

.wpcom-ai-feature-card.wpcom-ai-feature-card .wp-block-buttons {
	margin-top: 1.5rem;
}

.wpcom-ai-cta-button.wpcom-ai-cta-button .wp-block-button__link {
	min-width: 180px;
	text-align: center;
	padding: .9rem 2rem;
}

.wpcom-ai-modern-navigation {
	padding: 1rem clamp(1.25rem, 4vw, 4rem);
	box-shadow: 0 4px 18px rgba(11, 48, 59, 0.12);
}

.wpcom-ai-modern-navigation .wp-block-navigation-item__content {
	transition: opacity 160ms ease, transform 160ms ease;
}

.wpcom-ai-modern-navigation .wp-block-navigation-item__content:hover {
	opacity: .82;
	transform: translateY(-1px);
}"},"settings":{"color":{"palette":{"theme":[{"color":"#0b303b","name":"Primary","slug":"primary"},{"color":"#0b303b","name":"Secondary","slug":"secondary"},{"color":"#0b303b","name":"Foreground","slug":"foreground"},{"color":"#fef4ee","name":"Background","slug":"background"},{"color":"#F0F0F0","name":"Tertiary","slug":"tertiary"},{"color":"#6e2963","name":"Orange","slug":"custom-orange"},{"color":"#e2fdc7","name":"Green","slug":"custom-green"},{"color":"#2c3d87","name":"Purple","slug":"custom-purple"}]}}},"version":3,"isGlobalStylesUserThemeJSON":true}
